    sk=md.get('sessionKey','') or ''
    sess='TG' if 'telegram' in sk else ('SUB' if 'subagent' in sk else 'MAIN')
    if isinstance(c,str) and c.startswith('[tool start]'):
        # print tool name + first 2 lines of args
        lines=c.split('\n')
        name=lines[0].replace('[tool start]','').strip()
        arg=' '.join(lines[1:3])[:160]
