        for b in c:
            if isinstance(b,dict) and b.get('type')=='reasoning' and b.get('reasoning','').strip():
                print(f'{t(md.get(\"timestamp\",0))} [{i}] {sess} THINK: {b[\"reasoning\"][:400]}')
